261	InspectionBuffer *Ja3DetectGetHash(DetectEngineThreadCtx *det_ctx,
262	        const DetectEngineTransforms *transforms, Flow *_f, const uint8_t _flow_flags, void *txv,
263	        const int list_id)
264	{
