20	#[cfg(feature = "ja4")]
21	use crate::jsonbuilder::HEX;
22	#[cfg(feature = "ja4")]
23	use digest::Digest;
24	#[cfg(feature = "ja4")]
25	use sha2::Sha256;
26	#[cfg(feature = "ja4")]
27	use std::cmp::min;
28	#[cfg(feature = "ja4")]
29	use tls_parser::{TlsExtensionType, TlsVersion};
30	
31	use crate::handshake::HandshakeParams;
32	
33	pub const JA4_HEX_LEN: usize = 36;
34	
35	pub(crate) trait JA4Impl {
36	    fn try_new(hs: &HandshakeParams) -> Option<JA4>;
37	}
38	
39	#[derive(Debug, PartialEq)]
40	pub struct JA4 {
41	    hash: String,
42	}
43	
44	impl AsRef<str> for JA4 {
45	    fn as_ref(&self) -> &str {
46	        &self.hash
47	    }
48	}
49	
50	#[cfg(feature = "ja4")]
51	impl JA4 {
52	    #[inline]
53	    fn version_to_ja4code(val: Option<TlsVersion>) -> &'static str {
54	        match val {
55	            Some(TlsVersion::Tls13) => "13",
56	            Some(TlsVersion::Tls12) => "12",
57	            Some(TlsVersion::Tls11) => "11",
58	            Some(TlsVersion::Tls10) => "10",
59	            Some(TlsVersion::Ssl30) => "s3",
60	            // the TLS parser does not support SSL 1.0 and 2.0 hence no
61	            // support for "s1"/"s2"
62	            _ => "00",
63	        }
64	    }
65	
66	    fn format_alpn(alpn: Option<&Vec<u8>>) -> [char; 2] {
67	        let mut ret = ['0', '0'];
68	
69	        if let Some(alpn) = alpn {
70	            if !alpn.is_empty() {
71	                // If the first ALPN value is only a single character, then that character is treated as both the first and last character.
72	                if alpn.len() == 2 {
73	                    // GREASE values are 2 bytes, so this could be one -- check
74	                    let v: u16 = ((alpn[0] as u16) << 8) | alpn[alpn.len() - 1] as u16;
75	                    if HandshakeParams::is_grease(v) {
76	                        return ret;
77	                    }
78	                }
79	                if !alpn[0].is_ascii_alphanumeric() || !alpn[alpn.len() - 1].is_ascii_alphanumeric()
80	                {
81	                    // If the first or last byte of the first ALPN is non-alphanumeric (meaning not 0x30-0x39, 0x41-0x5A, or 0x61-0x7A), then we print the first and last characters of the hex representation of the first ALPN instead.
82	                    ret[0] = char::from(HEX[(alpn[0] >> 4) as usize]);
83	                    ret[1] = char::from(HEX[(alpn[alpn.len() - 1] & 0xF) as usize]);
84	                } else {
85	                    ret[0] = char::from(alpn[0]);
86	                    ret[1] = char::from(alpn[alpn.len() - 1]);
87	                }
88	            }
89	        }
90	        ret
91	    }
92	}
93	
94	#[cfg(feature = "ja4")]
95	impl JA4Impl for JA4 {
96	    fn try_new(hs: &HandshakeParams) -> Option<Self> {
97	        // All non-GREASE extensions are stored to produce a more verbose, complete output
98	        // of extensions but we need to omit ALPN & SNI extensions from the JA4_a hash.
99	        let mut exts = hs
100	            .extensions
101	            .iter()
102	            .filter(|&ext| {
103	                *ext != TlsExtensionType::ApplicationLayerProtocolNegotiation
104	                    && *ext != TlsExtensionType::ServerName
105	            })
106	            .collect::<Vec<&TlsExtensionType>>();
107	
108	        let alpn = Self::format_alpn(hs.alpns.first());
109	
110	        // Calculate JA4_a
111	        let ja4_a = format!(
112	            "{proto}{version}{sni}{nof_c:02}{nof_e:02}{al1}{al2}",
113	            proto = if hs.quic { "q" } else { "t" },
114	            version = Self::version_to_ja4code(hs.tls_version),
